// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value) public {
        vm.assume(value > 0);
        uint256 initialCount = c.depositsCount();
        deal(address(this), value);
        (bool ok, ) = address(c).call{value: value}("");
        require(ok, "receive reverted");
        uint256 newCount = c.depositsCount();
        assertTrue(newCount == initialCount + 1);
    }
}
